# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Metric-closure relay arborescence broadcast.

    Computes all-pairs shortest paths over h restricted to {src} ∪ dsts,
    builds a metric-closure digraph C whose edge weights are pairwise
    shortest-path costs, then computes a minimum-cost directed arborescence
    rooted at src on C. Each destination's delivery chain is the
    concatenation of closure-edge paths from src along the arborescence,
    permitting cheap dst→dst relay hops instead of forcing all traffic
    through src's egress. Every (dst, partition) receives a contiguous
    src→dst edge chain in G. Falls back to per-destination Dijkstra on any
    exception.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    def emit(dst, pairs):
        for s, t in pairs:
            for j in range(bc_topology.num_partitions):
                bc_topology.append_dst_partition_path(dst, j, [s, t, G[s][t]])

    def dijkstra_pairs(dst):
        p = nx.dijkstra_path(h, src, dst, weight="cost")
        return [(p[i], p[i + 1]) for i in range(len(p) - 1)]

    routes = None
    try:
        """Multi-candidate cost-tied Steiner alignment.

        Cost is charged per distinct directed edge in the emitted union, so
        the objective is minimum union (shared-edge) cost. We build several
        deterministic candidate union trees, each exploiting the freedom of
        choosing among cost-tied shortest paths, and keep the cheapest:
        (1) Takahashi-Matsuyama greedy growth under three destination
        orderings (farthest-first, nearest-first, input order). At each step
        the next dst is served by the candidate minimizing MARGINAL union
        cost against the already-paid edge set: up to 20 cost-tied shortest
        paths enumerated by bounded DFS over the shortest-path DAG (edges
        with dist[u]+cost(u,v)==dist[v]), plus an attachment path from the
        nearest already-paid tree node (one multi-source Dijkstra) spliced
        onto the tree path from src.
        (2) A metric-closure arborescence: all-pairs shortest paths among
        {src}∪dsts, Edmonds' minimum arborescence on the closure, expanded
        back into concrete shortest-path edge chains.
        Every chain is a concatenation of genuine shortest-path segments, so
        per-dst delivery cost is never worse than an arbitrary tie-break,
        while union-cost selection dedups shared (edge, partition) charges.
        Falls back to per-dst Dijkstra on any exception.
        """
        dist = nx.single_source_dijkstra_path_length(h, src, weight="cost")
        reach = [d for d in dsts if d != src and d in dist]
        if not reach:
            raise ValueError("no reachable dsts")

        def ecost(u, v):
            c = h[u][v].get("cost")
            return 1e6 if c is None else float(c)

        def dag_succ(v):
            dv = dist[v]
            return sorted(
                w for w in h.successors(v)
                if w in dist and abs(dv + ecost(v, w) - dist[w]) < 1e-9
            )

        def enum_paths(dst, limit=20):
            """Bounded DFS enumerating up to `limit` cost-tied DAG paths."""
            results, path = [], [src]

            def dfs(v):
                if len(results) >= limit:
                    return
                if v == dst:
                    results.append(list(path))
                    return
                for w in dag_succ(v):
                    path.append(w)
                    dfs(w)
                    path.pop()

            dfs(src)
            return results

        def path_pairs(p):
            return [(p[i], p[i + 1]) for i in range(len(p) - 1)]

        def greedy_candidate(order):
            """Greedy shared-tree growth minimizing marginal union cost."""
            tree = nx.DiGraph()
            tree.add_node(src)
            paid = set()
            chains = {}
            for dst in order:
                cands = []
                for p in enum_paths(dst):
                    pairs = path_pairs(p)
                    marg = sum(ecost(u, v) for u, v in pairs if (u, v) not in paid)
                    cands.append((marg, len(pairs), pairs))
                try:
                    _, ps = nx.multi_source_dijkstra(
                        h, list(tree.nodes()), dst, weight="cost"
                    )
                    root = ps[0]
                    tp = [src] if root == src else nx.shortest_path(tree, src, root)
                    full = path_pairs(tp) + path_pairs(ps)
                    marg = sum(ecost(u, v) for u, v in full if (u, v) not in paid)
                    cands.append((marg, len(full), full))
                except Exception:
                    pass
                if not cands:
                    chains[dst] = path_pairs(
                        nx.dijkstra_path(h, src, dst, weight="cost")
                    )
                else:
                    chains[dst] = min(cands, key=lambda c: (c[0], c[1]))[2]
                for u, v in chains[dst]:
                    if (u, v) not in paid:
                        paid.add((u, v))
                        tree.add_edge(u, v)
            return paid, chains

        def closure_candidate():
            """Metric-closure minimum arborescence expanded to edge chains."""
            terms = [src] + reach
            D = nx.DiGraph()
            for u in terms:
                du = nx.single_source_dijkstra_path_length(h, u, weight="cost")
                for v in terms:
                    if v != u and v in du:
                        D.add_edge(u, v, weight=du[v])
            arbo = nx.minimum_spanning_arborescence(D)
            paid, chains = set(), {}
            for dst in reach:
                ap = nx.shortest_path(arbo, src, dst)
                full = []
                for i in range(len(ap) - 1):
                    full += path_pairs(
                        nx.dijkstra_path(h, ap[i], ap[i + 1], weight="cost")
                    )
                chains[dst] = full
                paid.update(full)
            return paid, chains

        best = None
        for order in (
            sorted(reach, key=lambda d: -dist[d]),
            sorted(reach, key=lambda d: dist[d]),
            list(reach),
        ):
            paid, chains = greedy_candidate(order)
            uc = sum(ecost(u, v) for u, v in paid)
            if best is None or uc < best[0]:
                best = (uc, chains)
        try:
            paid, chains = closure_candidate()
            uc = sum(ecost(u, v) for u, v in paid)
            if uc < best[0]:
                best = (uc, chains)
        except Exception:
            pass
        routes = best[1]
    except Exception:
        routes = None

    if routes is None:
        for dst in dsts:
            emit(dst, dijkstra_pairs(dst))
        return bc_topology

    for dst in dsts:
        emit(dst, routes[dst])

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


